ccsFlapPowerAdjustThreshold = MibScalar((1, 3, 6, 1, 4, 1, 9, 9, 114, 1, 1, 6), Integer32().subtype(subtypeSpec=ValueRangeConstraint(1, 10)).clone(1)).setUnits('db').setMaxAccess("readwrite")
